/** A small Creality-Print-shaped file built in code (no design IP), for tests that must always run. */
export function syntheticGcode(opts: {
  objects: { name: string; ids: string[] }[];
  totalGrams: number;
  timeSeconds?: number;
  filler?: number;
}): string {
  const lines = [
    `;TIME:${opts.timeSeconds ?? 3600}`,
    ";Filament used:1.0m",
    ";Layer height:0.200",
    "; HEADER_BLOCK_START",
    "; generated by Creality_Print V7.3.2.6412 on 2026-11-24 at 10:00:00",
    "; total layer number: 10",
    "; HEADER_BLOCK_END",
    "; THUMBNAIL_BLOCK_START",
    "; png begin 2*2 100 0 0 1",
    "; iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAEklEQVR4nGP4z8DAwMDAxAADAAkMAQBUiIdwAAAAAElFTkSuQmCC",
    "; png end",
    "; THUMBNAIL_BLOCK_END",
    ";LAYER_CHANGE",
  ];
  for (let layer = 0; layer < 2; layer++) {
    for (const o of opts.objects) {
      for (const id of o.ids) {
        lines.push(`; printing object ${o.name} id:${id} copy 0`);
        for (let i = 0; i < (opts.filler ?? 5); i++) lines.push(`G1 X${i} Y${i} E0.01`);
        lines.push(`; stop printing object ${o.name} id:${id} copy 0`);
      }
    }
    lines.push(";LAYER_CHANGE");
  }
  lines.push(
    "; filament used [mm] = 1000.00",
    "; filament used [cm3] = 2.41",
    `; filament used [g] = ${opts.totalGrams}`,
    `; total filament used [g] = ${opts.totalGrams}`,
    "; estimated printing time (normal mode) = 1h 0m 0s",
    "; CONFIG_BLOCK_START",
    "; filament_colour = #000000",
    "; filament_type = PLA",
    "; nozzle_diameter = 0.4",
    "; printer_model = Creality Ender-3 V3 SE",
    "; printer_settings_id = Creality Ender-3 V3 SE 0.4 nozzle",
    "; CONFIG_BLOCK_END",
  );
  return lines.join("\n") + "\n";
}

/** A small PrusaSlicer-shaped file (plain ASCII G-code, settings in `prusaslicer_config`). */
export function syntheticPrusaGcode(opts: {
  totalGrams: number;
  objects?: { name: string; ids: string[] }[];
  printerSettingsId?: string;
  supports?: boolean;
  thumbnail?: boolean;
}): string {
  const lines = ["; generated by PrusaSlicer 2.8.1+win64 on 2026-11-25 at 12:00:00 UTC", ";", ""];
  if (opts.thumbnail) {
    lines.push(
      ";",
      "; thumbnail begin 2x2 112",
      "; iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAEklEQVR4nGP4z8DAwMDAxAADAAkMAQBUiIdwAAAAAElFTkSuQmCC",
      "; thumbnail end",
      ";",
    );
  }
  lines.push("; external perimeters extrusion width = 0.42mm", "G28", ";LAYER_CHANGE", ";Z:0.2");
  for (const o of opts.objects ?? []) {
    for (const id of o.ids) {
      lines.push(`; printing object ${o.name} id:${id} copy 0`, "G1 X1 Y1 E0.1");
      lines.push(`; stop printing object ${o.name} id:${id} copy 0`);
    }
  }
  lines.push(
    "M84",
    "; filament used [mm] = 2000.50",
    "; filament used [cm3] = 4.81",
    `; filament used [g] = ${opts.totalGrams}`,
    "; filament cost = 0.15",
    `; total filament used [g] = ${opts.totalGrams}`,
    "; total filament cost = 0.15",
    "; estimated printing time (normal mode) = 2h 3m 4s",
    "; estimated printing time (silent mode) = 2h 3m 0s",
    "",
    "; prusaslicer_config = begin",
    "; bed_temperature = 60",
    "; filament_colour = #FF8000",
    "; filament_cost = 20",
    "; filament_type = PETG",
    "; fill_density = 20%",
    "; fill_pattern = gyroid",
    "; layer_height = 0.2",
    "; nozzle_diameter = 0.4",
    "; perimeters = 3",
    "; printer_model = ",
    `; printer_settings_id = ${opts.printerSettingsId ?? "Creality Ender-3 V3 SE"}`,
    `; support_material = ${opts.supports ? 1 : 0}`,
    "; support_material_style = organic",
    "; temperature = 240",
    "; prusaslicer_config = end",
  );
  return lines.join("\n") + "\n";
}

/**
 * A file from an unknown slicer: only moves. 10 lines of 10 mm each, extruding 0.5 mm per line,
 * with a retract/unretract in between and a G92 reset (absolute) — or relative E with M83.
 */
export function syntheticMovesOnly(opts: { relative?: boolean; header?: string } = {}): string {
  const lines = [
    opts.header ?? "; made by HandRolledSlicer 0.1",
    "G28",
    "G90",
    opts.relative ? "M83" : "M82",
    "G92 E0",
  ];
  lines.push("G1 Z0.2 F600", "G1 X0 Y0 F6000");
  let e = 0;
  for (let i = 0; i < 10; i++) {
    const y = i % 2 === 0 ? 10 : 0;
    if (opts.relative) lines.push(`G1 X${i} Y${y} E0.5 F1200`);
    else lines.push(`G1 X${i} Y${y} E${(e += 0.5).toFixed(2)} F1200`);
    if (i === 4) {
      lines.push(opts.relative ? "G1 E-0.8 F2400" : `G1 E${(e - 0.8).toFixed(2)} F2400`);
      lines.push(opts.relative ? "G1 E0.8 F2400" : `G1 E${e.toFixed(2)} F2400`);
    }
    if (i === 5 && !opts.relative) {
      lines.push("G92 E0");
      e = 0;
    }
  }
  lines.push("M84");
  return lines.join("\n") + "\n";
}

/** A small Cura-shaped file (Marlin flavour). */
export function syntheticCuraGcode(): string {
  return [
    ";FLAVOR:Marlin",
    ";TIME:5025",
    ";Filament used: 4.56789m",
    ";Layer height: 0.2",
    ";MINX:10",
    ";Generated with Cura_SteamEngine 5.7.1",
    "M140 S60",
    ";LAYER_COUNT:90",
    ";LAYER:0",
    "G1 X1 Y1 E0.1",
    "M84",
    ";End of Gcode",
    ';SETTING_3 {"global_quality": "[general]\\\\nversion = 4\\\\n[values]\\\\nlayer_height = 0.2\\\\nsupport_enab',
    ';SETTING_3 le = False\\\\n", "extruder_quality": ["[general]\\\\n[values]\\\\ninfill_sparse_density = 20\\\\nmateria',
    ';SETTING_3 l_print_temperature = 205\\\\nwall_line_count = 3\\\\n"]}',
    "",
  ].join("\n");
}

/** A small Simplify3D-shaped file. */
export function syntheticSimplify3dGcode(): string {
  return [
    "; G-Code generated by Simplify3D(R) Version 5.1.2",
    "; Mar 1, 2026 at 10:00:00 AM",
    "; Settings Summary",
    ";   processName,Process1",
    ";   extruderDiameter,0.4",
    ";   layerHeight,0.24",
    ";   perimeterOutlines,2",
    ";   infillPercentage,25",
    ";   generateSupport,0",
    ";   temperatureSetpointTemperatures,215,60",
    "G28",
    "G1 X1 Y1 E0.1",
    "M84",
    "; Build Summary",
    ";   Build time: 1 hours 32 minutes",
    ";   Filament length: 5123.4 mm (5.12 m)",
    ";   Plastic volume: 12323.45 mm^3 (12.32 cc)",
    ";   Plastic weight: 15.28 g (0.03 lb)",
    ";   Material cost: 0.38",
    "",
  ].join("\n");
}
